-- 서버 구조 스냅숏을 뽑는 SQL (구조만 — 회원 데이터는 들어 있지 않다)
-- Supabase SQL Editor(또는 MCP execute_sql)에서 실행 → 결과 JSON 을 파일로 저장 → python tools/backup/make_snapshot.py <파일>
select json_build_object(
 'functions', (select json_agg(json_build_object('name',p.proname,'args',pg_get_function_identity_arguments(p.oid),'def',pg_get_functiondef(p.oid),'acl',p.proacl::text) order by p.proname, pg_get_function_identity_arguments(p.oid)) from pg_proc p where p.pronamespace='public'::regnamespace and p.prokind='f' and not exists (select 1 from pg_depend d where d.objid=p.oid and d.deptype='e')),
 'tables', (select json_agg(json_build_object('t',c.relname,'rls',c.relrowsecurity,'cols',(select json_agg(json_build_object('n',a.attname,'ty',format_type(a.atttypid,a.atttypmod),'nn',a.attnotnull,'def',pg_get_expr(ad.adbin,ad.adrelid)) order by a.attnum) from pg_attribute a left join pg_attrdef ad on ad.adrelid=a.attrelid and ad.adnum=a.attnum where a.attrelid=c.oid and a.attnum>0 and not a.attisdropped),'cons',(select json_agg(json_build_object('n',conname,'def',pg_get_constraintdef(oid)) order by conname) from pg_constraint where conrelid=c.oid),'acl',c.relacl::text) order by c.relname) from pg_class c where c.relnamespace in ('public'::regnamespace,'archive'::regnamespace) and c.relkind='r'),
 'indexes', (select json_agg(indexdef order by indexname) from pg_indexes where schemaname='public'),
 'policies', (select json_agg(json_build_object('s',schemaname,'t',tablename,'n',policyname,'cmd',cmd,'roles',roles::text,'using',qual,'check',with_check) order by schemaname,tablename,policyname) from pg_policies where schemaname in ('public','storage')),
 'triggers', (select json_agg(pg_get_triggerdef(t.oid) order by t.tgrelid::regclass::text, t.tgname) from pg_trigger t join pg_class c on c.oid=t.tgrelid where not t.tgisinternal and c.relnamespace in ('public'::regnamespace,'auth'::regnamespace,'storage'::regnamespace) and t.tgname not like 'RI_%'),
 'cron', (select json_agg(json_build_object('job',jobname,'schedule',schedule,'command',command,'active',active) order by jobname) from cron.job),
 'col_grants', (select json_agg(json_build_object('t',table_name,'c',column_name,'p',privilege_type,'g',grantee)) from information_schema.column_privileges where table_schema='public' and grantee in ('authenticated','anon') and table_name in (select table_name from information_schema.column_privileges where table_schema='public' and grantee='authenticated' group by table_name, privilege_type having count(*) < (select count(*) from information_schema.columns c2 where c2.table_schema='public' and c2.table_name=column_privileges.table_name))),
 'buckets', (select json_agg(json_build_object('id',id,'public',public,'limit',file_size_limit,'mime',allowed_mime_types)) from storage.buckets),
 'extensions', (select json_agg(extname||' '||extversion||' @'||n.nspname) from pg_extension e join pg_namespace n on n.oid=e.extnamespace),
 'views', (select json_agg(json_build_object('v',viewname,'def',definition)) from pg_views where schemaname='public'),
 'types', (select json_agg(json_build_object('t',t.typname,'vals',(select json_agg(enumlabel order by enumsortorder) from pg_enum where enumtypid=t.oid))) from pg_type t where t.typnamespace='public'::regnamespace and t.typtype='e'),
 'app_config', (select json_object_agg(key, case when key in ('guides','home_notice','chat_theme','ddeuchin_event','min_version','supporters_enabled','shops_everywhere') then value else null end) from app_config),
 'migrations', (select json_agg(version||' '||name order by version) from supabase_migrations.schema_migrations)
) as snapshot;
